import { useTranslation } from "react-i18next";
import { StatCard } from "@/components/ui/StatCard";
import { Skeleton } from "@/components/ui/Skeleton";
import { useGetOrdersOriginMetrics } from "@/lib/api";
import { formatMoney } from "@/lib/formatMoney";

interface OriginMetricsProps {
	from?: string;
	to?: string;
	unitId?: string;
}

/** Orders, revenue and average ticket generated by the Instagram link in bio (sold orders only). */
export function OriginMetrics({ from, to, unitId }: OriginMetricsProps) {
	const { t } = useTranslation();
	const { data, isError, isPending } = useGetOrdersOriginMetrics({
		...(from ? { from } : {}),
		...(to ? { to } : {}),
		...(unitId ? { unitId } : {}),
	});
	if (isError) return null;
	return (
		<div className="grid shrink-0 gap-3 sm:grid-cols-3">
			{isPending ? (
				[0, 1, 2].map(index => <Skeleton className="h-[5.5rem] w-full" key={index} />)
			) : (
				<>
					<StatCard hint={t("admin.orders.origin.metrics.hint")} label={t("admin.orders.origin.metrics.orders")} value={data.bio.orders} />
					<StatCard label={t("admin.orders.origin.metrics.revenue")} value={formatMoney(data.bio.revenueCents / 100)} />
					<StatCard label={t("admin.orders.origin.metrics.ticket")} value={formatMoney(data.bio.averageTicketCents / 100)} />
				</>
			)}
		</div>
	);
}
